def prefix_stock(events):
    root = [0, {}]
    stock = {}
    answers = []
    for event in events:
        if event[0] == 'set':
            code, count = event[1], event[2]
            change = count - stock.get(code, 0)
            stock[code] = count
            node = root
            node[0] += change
            for ch in code:
                node = node[1].setdefault(ch, [0, {}])
                node[0] += change
        else:
            node = root
            for ch in event[1]:
                node = node[1].get(ch)
                if node is None:
                    break
            answers.append(0 if node is None else node[0])
    return answers

