import bisect

def prefix_stock(events):
    # codes in a sorted list; an ask bisects to the prefix and adds up every match
    codes = []
    stock = {}
    out = []
    for e in events:
        if e[0] == "set":
            if e[1] not in stock:
                bisect.insort(codes, e[1])
            stock[e[1]] = e[2]
        else:
            p = e[1]
            i = bisect.bisect_left(codes, p)
            total = 0
            while i < len(codes) and codes[i].startswith(p):
                total += stock[codes[i]]
                i += 1
            out.append(total)
    return out
